import type { ChatMessage } from "../contracts";
/** executeControl supplies instructions and schema once, through Inference's shared output contract. */
export function buildMessages(data: unknown): ChatMessage[] {
	return [{ role: "user", content: JSON.stringify(data) }];
}

/**
 * A step's own `## Task` after the conversation's prefix (the conversation input specification, section 10): the
 * input only. executeControl adds the step's instructions and schema to the first system message.
 */
export function taskText(data: unknown): string {
	return `入力:\n${JSON.stringify(data)}`;
}

