import { expect, test } from "bun:test";
import { operationOutputMessages } from "../domains/inference/contracts/operation-output";
import { buildMessages, taskText } from "../domains/steward/service/messages";

const contract = {
	instructions: "Judge the supplied evidence; preserve uncertainty.",
	outputSchema: {
		type: "object",
		properties: { remember: { type: "array", items: { type: "string" } } },
		required: ["remember"],
		additionalProperties: false,
	},
};
const data = {
	events: [{ id: "e7", by: "user", text: "普段は紅茶。今日はコーヒー。" }],
	longTerm: [{ ref: "lm1", origin: "agent_inferred", text: "紅茶を好む" }],
	longTermCoverage: { stateTotal: 10, stateShown: 1 },
};

test("an independent steward call receives the entire output contract once through Inference", () => {
	const messages = operationOutputMessages(buildMessages(data), contract);
	expect(messages).toEqual([
		{
			role: "system",
			content: `${contract.instructions}\nOUTPUT_SCHEMA=${JSON.stringify(contract.outputSchema)}`,
		},
		{ role: "user", content: JSON.stringify(data) },
	]);
});

test("a shared-conversation call keeps its records and presents the contract only in the first system", () => {
	const shared = [
		{ role: "system" as const, content: "Conversation instructions" },
		{ role: "user" as const, content: "## Memory\n- 紅茶を好む（推定）" },
		{ role: "assistant" as const, content: "飲み物はどうしましょう。" },
	];
	const messages = operationOutputMessages(
		[...shared, { role: "user", content: `## Task\n${taskText(data)}` }],
		contract,
	);
	expect(messages[0]!.content).toBe(
		`${shared[0]!.content}\n${contract.instructions}\nOUTPUT_SCHEMA=${JSON.stringify(contract.outputSchema)}`,
	);
	expect(messages.slice(1, 3)).toEqual(shared.slice(1));
	expect(messages[3]!.content).toBe(`## Task\n入力:\n${JSON.stringify(data)}`);
	expect(
		messages
			.map((m) => m.content)
			.join("\n")
			.split("OUTPUT_SCHEMA="),
	).toHaveLength(2);
});
